const holes = (hs = []) => hs.map(h => `.pushPoints([(${h.x}, ${h.y})]).hole(${h.diameter})`).join('');
export function generateCadQuery(spec) { const p = spec.part; if (!p)
    return { supported: false, code: '', message: 'Only part specs are supported.' }; const a = p.parameters; if (p.type === 'rounded_rectangular_plate')
    return { supported: true, code: `# Generated by printspec 0.1.0\nimport cadquery as cq\n\nlength = ${a.length}\nwidth = ${a.width}\nheight = ${a.thickness}\ncorner_radius = ${a.cornerRadius}\n\npart = cq.Workplane("XY").rounded_rect(length, width, corner_radius).extrude(height)${holes(a.holes)}\n` }; if (p.type === 'spacer_block')
    return { supported: true, code: `# Generated by printspec 0.1.0\nimport cadquery as cq\n\nlength = ${a.length}\nwidth = ${a.width}\nheight = ${a.height}\n\npart = cq.Workplane("XY").box(length, width, height, centered=(True, True, False))${holes(a.holes)}\n` }; return { supported: false, code: '', message: `Unsupported part family: ${p.type}` }; }
